package com.MITProjectService.bot.enums;import lombok.AllArgsConstructor;import lombok.Getter;@AllArgsConstructor@Getterpublic enum CommonEnums {    ENABLE(1),    DISABLE(0);    private final int value;    public static CommonEnums fromValue(int value) {        for (CommonEnums status : values()) {            if (status.value == value) {                return status;            }        }        throw new IllegalArgumentException("Invalid CommonEnums value: " + value);    }    public static CommonEnums fromName(String name) {        try {            return CommonEnums.valueOf(name.toUpperCase());        } catch (IllegalArgumentException e) {            throw new IllegalArgumentException("Invalid CommonEnums name: " + name, e);        }    }}